 function bindDeviceUsage(state,owner,progress){if(typeof owner!=='string'||!owner||!validProgress(progress))throw Error('usage-scope');initializeDeviceUsage(state);const old=state.playUsageOwner;if(old&&old!==owner){state.playUsageScopes=state.playUsageScopes||{};state.playUsageScopes[old]={usage:structuredClone(state.playProgress.usage),pending:structuredClone(state.playPending)};state.playPending=structuredClone(state.playUsageScopes[owner]?.pending||[]);}state.playUsageOwner=owner;state.playProgress=structuredClone(progress);initializeDeviceUsage(state);for(const event of state.playPending)apply(state.playProgress,event);return state;}
 function validProgress(p,hasChar=()=>true){return !!p&&typeof p==='object'&&p.usage&&p.challenges&&Object.keys(p.usage).length<=10142&&Object.entries(p.usage).every(([c,v])=>hasChar(c)&&v&&keys.every(k=>Number.isInteger(v[k])&&v[k]>=0&&v[k]<=1e9)&&(v.honorWins===undefined||Number.isInteger(v.honorWins)&&v.honorWins>=0&&v.honorWins<=v.wins)&&v.wins<=v.plays&&v.survived<=v.plays)&&Object.keys(p.challenges).length<=catalogue.length&&Object.entries(p.challenges).every(([id,v])=>get(id)&&v&&['attempts','clears','bestSurvivors'].every(k=>Number.isInteger(v[k])&&v[k]>=0&&v[k]<=1e9)&&v.clears<=v.attempts&&v.bestSurvivors<=3&&(v.bestShots===null||Number.isInteger(v.bestShots)&&v.bestShots>=0&&v.bestShots<=1000));}
