 function apply(progress,event){for(const i of event.items){const v=progress.usage[i.char]||emptyUsage();v.plays++;v.wins+=event.outcome==='win'?1:0;v.honorWins=(v.honorWins||0)+(event.outcome==='win'&&get(event.challenge)?.kind!=='cpu-skill'?1:0);v.survived+=i.survived?1:0;v.shots+=i.shots;v.kills+=i.kills;v.bestShot=Math.max(v.bestShot,i.bestShot);progress.usage[i.char]=v;}if(event.challenge){const old=progress.challenges[event.challenge]||{attempts:0,clears:0,bestShots:null,bestSurvivors:0};old.attempts++;if(event.cleared){old.clears++;old.bestShots=old.bestShots===null?event.shots:Math.min(old.bestShots,event.shots);old.bestSurvivors=Math.max(old.bestSurvivors,event.survivors);}progress.challenges[event.challenge]=old;}return progress;}
 function condition(id,team,countStrokes){const c=get(id);id=c?.conditionId||id;if(!c)return'挑戦を選んでください。';if(c.kind==='cpu-skill')return '';if(c.kind==='one-shot')return team.length?'':'編成・ルビで発射する文字を用意してください。';if(team.length!==3)return'自分を3体編成してください。';if(id==='first-tier'&&team.some(i=>i.jis!==1))return'自分3体をJIS第1水準にしてください。';if(id==='few-strokes'&&team.reduce((sum,i)=>sum+countStrokes(i),0)>12)return'自分3体の総画数を12画以下にしてください。';if(id==='three-elements'&&new Set(team.map(i=>i.attr)).size!==3)return'自分3体をそれぞれ異なる属性にしてください。';if(id==='one-element'&&new Set(team.map(i=>i.attr)).size!==1)return'自分3体を同じ属性にしてください。';return'';}
 function prepareTeam(id,team,selected){const c=get(id),items=c.kind==='one-shot'?[team.find(i=>i.instanceId===selected)||team[0]]:team;return items.filter(Boolean).map(i=>({...i,level:c.playerLevel==='owned'?Math.max(1,Math.min(100,i.level||1)):c.playerLevel||10,exp:0,ruby:id==='no-ruby'?'':i.ruby,equippedReadings:id==='no-ruby'?[]:i.equippedReadings.slice(),unlockedReadings:i.unlockedReadings?.slice(),teamLink:undefined}));}
 function levelLabel(id){const c=get(id);if(c?.kind==='cpu-skill')return '貸出3体・Lv.10・ルビなし・配置固定';return c?.playerLevel==='owned'?'所持レベル・装備ルビを使用':`Lv.${c?.playerLevel||10}統一・装備ルビを使用`;}
 function createUsage(id,team){return{id,settled:false,items:team.map(i=>({instanceId:i.instanceId,char:i.char,shots:0,kills:0,bestShot:0})),shot:null,shots:0};}
 function launch(run,instanceId,strength=0){if(!run||run.settled)return;const item=run.items.find(i=>i.instanceId===instanceId);if(!item)return;run.shots++;item.shots++;if(run.cpuSkill?.version===2)run.cpuSkill.powers.push(Math.round(Math.max(0,Math.min(100,strength))*10));run.shot={instanceId,kills:0};}
