 function event(run,winner,survivorIds,challenge=null){if(!run||run.settled)return null;run.settled=true;const byChar=new Map();for(const i of run.items){const v=byChar.get(i.char)||{char:i.char,shots:0,kills:0,bestShot:0,survived:false};v.shots+=i.shots;v.kills+=i.kills;v.bestShot=Math.max(v.bestShot,i.bestShot);v.survived||=survivorIds.includes(i.instanceId);byChar.set(i.char,v);}const cleared=winner===true&&!!challenge&&((get(challenge)?.conditionId||challenge)!=='all-killed'||run.items.length===3&&run.items.every(i=>i.kills>=1))&&((get(challenge)?.conditionId||challenge)!=='intact'||survivorIds.length===3)&&((get(challenge)?.conditionId||challenge)!=='swift'||run.shots<=3)&&(get(challenge)?.kind!=='one-shot'||run.shots===1&&run.items.some(i=>i.bestShot===3));return{...(run.cpuSkill?{cpuSkill:run.cpuSkill.version===3?{...run.cpuSkill,killTurns:[...run.cpuSkill.killTurns,...Array(Math.max(0,3-run.cpuSkill.killTurns.length)).fill(run.shots+1)]}:{...run.cpuSkill,powers:run.cpuSkill.powers.slice()}}:{}),id:run.id,items:[...byChar.values()],outcome:winner===true?'win':winner===false?'loss':'draw',challenge,cleared,shots:run.shots,survivors:survivorIds.length};}
